 useEffect(()=>{if(!entered)return;let raf=0,last=performance.now();const tick=(now:number)=>{const dt=Math.min((now-last)/1000,.033);last=now;let ix=0,iy=0;const k=keysRef.current;if(k.has("a")||k.has("arrowleft"))ix--;if(k.has("d")||k.has("arrowright"))ix++;if(k.has("w")||k.has("arrowup"))iy--;if(k.has("s")||k.has("arrowdown"))iy++;if(!ix&&!iy&&(Math.abs(stickRef.current.x)>.08||Math.abs(stickRef.current.y)>.08)){ix=stickRef.current.x;iy=stickRef.current.y}if(!ix&&!iy&&targetRef.current){const tx=targetRef.current.x-posRef.current.x,ty=targetRef.current.y-posRef.current.y,d=Math.hypot(tx,ty);if(d<.55){targetRef.current=null;setTarget(null)}else{ix=tx/d;iy=ty/d}}const blocked=!!active||!!chosen;if(blocked){ix=0;iy=0}const inputMag=Math.hypot(ix,iy);if(inputMag>1){ix/=inputMag;iy/=inputMag}const response=1-Math.exp(-(inputMag?16:22)*dt),velocity=velocityRef.current;velocity.x+=(ix*SPEED-velocity.x)*response;velocity.y+=(iy*SPEED-velocity.y)*response;if(Math.abs(velocity.x)<.025)velocity.x=0;if(Math.abs(velocity.y)<.025)velocity.y=0;const speed=Math.hypot(velocity.x,velocity.y);if(speed>.035&&!blocked){idleRef.current=now;setIdleMessage(false);let nx=Math.max(6,Math.min(94,posRef.current.x+velocity.x*dt)),ny=Math.max(10,Math.min(91,posRef.current.y+velocity.y*dt));if(!walkable(nx,ny)){if(walkable(nx,posRef.current.y))ny=posRef.current.y;else if(walkable(posRef.current.x,ny))nx=posRef.current.x;else{nx=posRef.current.x;ny=posRef.current.y;velocity.x=0;velocity.y=0;targetRef.current=null;setTarget(null)}}const next={x:nx,y:ny};posRef.current=next;setPos(next);setMoving(true);setWalkFrame(Math.floor(now/125)%4);if(now-lastStepRef.current>300){lastStepRef.current=now;footstep()}if(Math.abs(velocity.x)>Math.abs(velocity.y))setFacing(velocity.x>0?"right":"left");else setFacing(velocity.y>0?"down":"up");if(companion){const trail=trailRef.current;trail.push({...next});const follow=trail.length>18?trail.shift()!:trail[0],current=companionPosRef.current,fdx=follow.x-current.x,fdy=follow.y-current.y;companionPosRef.current=follow;setCompanionPos(follow);setCompanionMoving(Math.hypot(fdx,fdy)>.012);setCompanionFrame(Math.floor(now/135)%4);if(Math.abs(fdx)>.012||Math.abs(fdy)>.012){if(Math.abs(fdx)>Math.abs(fdy))setCompanionFacing(fdx>0?"right":"left");else setCompanionFacing(fdy>0?"down":"up")}}}else{setMoving(false);setCompanionMoving(false);if(!idleRef.current)idleRef.current=now;if(now-idleRef.current>5200)setIdleMessage(true)}raf=requestAnimationFrame(tick)};raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf)},[entered,active,chosen,footstep,companion]);
 const setDestination=(e:React.PointerEvent<HTMLElement>)=>{if(active||chosen||(e.target as HTMLElement).closest("button,.joystick,.signal"))return;const r=e.currentTarget.getBoundingClientRect();setTarget({x:Math.max(6,Math.min(94,(e.clientX-r.left)/r.width*100)),y:Math.max(10,Math.min(91,(e.clientY-r.top)/r.height*100))})};
 const steer=(e:React.PointerEvent<HTMLDivElement>)=>{const base=stickBaseRef.current;if(!base)return;const r=base.getBoundingClientRect(),radius=r.width*.34;let x=(e.clientX-(r.left+r.width/2))/radius,y=(e.clientY-(r.top+r.height/2))/radius;const m=Math.hypot(x,y);if(m>1){x/=m;y/=m}stickRef.current={x,y};setStick({x,y,active:true});setTarget(null)};
