 const locateDrop=(e:React.PointerEvent<HTMLElement>)=>{const stage=e.currentTarget.closest(".ritual-stage") as HTMLElement|null;if(!stage)return dropPos;const r=stage.getBoundingClientRect();return{x:Math.max(5,Math.min(95,(e.clientX-r.left)/r.width*100)),y:Math.max(5,Math.min(92,(e.clientY-r.top)/r.height*100))}};
 const beginDrop=(e:React.PointerEvent<HTMLElement>)=>{if(awakening)return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);setDraggingDrop(true)};
 const moveDrop=(e:React.PointerEvent<HTMLElement>)=>{if(!draggingDrop||awakening)return;e.preventDefault();setDropPos(locateDrop(e))};
 const releaseDrop=(e:React.PointerEvent<HTMLElement>)=>{if(!draggingDrop||awakening)return;const p=locateDrop(e);setDraggingDrop(false);if(Math.hypot(p.x-50,(p.y-48)*.9)<23){setDropPos({x:50,y:48});setAwakenPhase(0);setAwakening(true)}else setDropPos({x:23,y:60})};
 const finishAwakening=()=>{if(!chosen)return;const hatch=chosen,spawn={x:Math.max(7,Math.min(93,posRef.current.x-5)),y:Math.max(12,Math.min(90,posRef.current.y+3))};velocityRef.current={x:0,y:0};targetRef.current=null;trailRef.current=Array.from({length:18},()=>({...spawn}));companionPosRef.current=spawn;setTarget(null);setMoving(false);setCompanionPos(spawn);setCompanionFacing("down");setCompanionFrame(0);setCompanionMoving(false);setCompanion(hatch);setChosen(null);setActive(null);setAwakening(false);setAwakenPhase(0);setHint(`${rituals[hatch.id].result} has awakened. Lead them to the First Well.`)};
 useEffect(()=>{if(!chosen||!awakening||awakenPhase<3)return;const timer=window.setTimeout(finishAwakening,1150);return()=>window.clearTimeout(timer)},[chosen,awakening,awakenPhase]);
