 return <main className={`game keeper-${keeperPalette}`}><header><div><p className="eyebrow">The Dormant Hollow</p><h1>{companion?`Guide ${rituals[companion.id].result}`:"Follow the living signals"}</h1></div><div className="hudcluster"><button className="sound-toggle mantle-button" onClick={()=>setKeeperPalette(v=>keeperPalettes[(keeperPalettes.findIndex(k=>k.id===v)+1)%keeperPalettes.length].id)} aria-label="Change Wellkeeper mantle">Mantle · {keeperPalettes.find(k=>k.id===keeperPalette)?.name}</button><button className="sound-toggle" onClick={()=>setSoundOn(v=>!v)} aria-label={`${soundOn?"Mute":"Enable"} terrain sound`}>{soundOn?"Sound ◉":"Sound ○"}</button><div className="gauge"><i className="minidrop"/><span><small>Living vessel</small><b>{companion?"Drop offered":"1 final drop"}</b></span></div></div></header>
